Method.Implementation:
	 Set tSC = $$$OK
	 If $Length($ZStrip(Msg,"<>W"))>106
     {
	 Set SegDelim = $Extract(Msg,106)
     }
     Else
	 {
		 Set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).InputDataError(ConfigName,"Unable to retrieve segment delimiter from  <" _Msg_ "> because the message is too short")
	 }
	 Quit tSC

	 Set tSC = $$$OK
	 If $Length($ZStrip(Msg,"<>W"))>106
     {
	 Set FieldDelim = $Extract(Msg,104)
	 }
     Else
     {
		 Set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).InputDataError(ConfigName,"Unable to retrieve field delimiter from  <" _Msg_ "> because the message is too short")
	 }
	 Quit tSC
